#: **H-C was tested and REFUTED** (2026-11-02): no constant-coefficient recurrence of order <= 7 reproduces the 37
#: conifold coefficients (c0..c5 = 1, 37/30, 2309/1800, 286471/225000, 41932661/33750000, 237108737/196875000). So the
#: sequence is not C-finite at low order, its generating function is not a small rational function, and the arithmetic
#: null is NOT explained by rationality -- it stands as a bounded wall.
#:
#: **Instrument warning:** a Berlekamp-Massey run on 40 terms returned an order-20 recurrence with enormous rational
#: coefficients and verified perfectly. That is the classic overfit, not a discovery. Recurrence claims must be tested
#: OUT OF SAMPLE at LOW order, or they measure the number of terms.

#: Valid statuses.
STATUSES = ("open", "supported", "refuted")


def _wall_names() -> set:
    return {name for name, *_rest in walls.REGISTER}


DECIDED = ("supported", "refuted")

#: Assigned priors (hid -> P(H)), documented and reproducible — the same convention as
#: ``retrofit.CONFIDENCE_PRIOR``. To be calibrated against outcomes as they land.
BELIEF_PRIOR = {
    "H-A": 0.50,
    "H-B": 0.55,
    "H-C": 0.45,
    "H-D": 0.50,
    "H-E": 0.60,
    "H-F": 0.70,
}

#: An assumed, calibratable test: 80% sensitive, 20% false-positive. The Bayes factor a
#: status implies comes from THIS likelihood — stated so it can be corrected later.
STANDARD_TEST = Likelihood(0.80, 0.20)


def belief_view() -> list[tuple[str, float, float, float]]:
    """The numeric belief per hypothesis: ``(hid, prior, B, posterior)``.

    ``supported`` -> a positive result under STANDARD_TEST (B = tp/fp);
    ``refuted``   -> a negative result (B = (1-tp)/(1-fp));
    ``open``      -> no test yet, B = 1 and posterior = prior.
    """
    out = []
    for hid, title, cited, claim, predicts, test, status, script in HYPOTHESES:
        prior = BELIEF_PRIOR[hid]
        if status == "supported":
            b, post = bayes_factor(STANDARD_TEST, True), posterior(prior, STANDARD_TEST, True)
        elif status == "refuted":
            b, post = bayes_factor(STANDARD_TEST, False), posterior(prior, STANDARD_TEST, False)
        else:
            b, post = 1.0, prior
        out.append((hid, prior, b, post))
    return out


def check_links() -> dict:
    """Every cited wall must exist in the register, and each hypothesis must pair at least two."""
    known = _wall_names()
    missing, thin = [], []
    for hid, title, cited, claim, predicts, test, status, script in HYPOTHESES:
        for w in cited:
            if w not in known:
                missing.append((hid, w))
        if len(set(cited)) < 2:
            thin.append(hid)
    return {"missing": missing, "too_few_walls": thin, "ok": not missing and not thin}


def check_artefacts() -> dict:
    """**The claims-registry rule.** A decided hypothesis must name a script that exists in the repository.

    ``open`` may say "no executable test" (script is None). A ``supported`` or ``refuted`` hypothesis with no script is
    a claim nobody can re-run -- the defect the claims-registry guard caught on its first run, when a script it cited
    did not exist at all.
    """
    unbacked, broken = [], []
    for hid, title, cited, claim, predicts, test, status, script in HYPOTHESES:
        if status in DECIDED:
            if not script:
                unbacked.append(hid)
            elif not (ROOT / "scripts" / script).is_file():
                broken.append((hid, script))
        elif script and not (ROOT / "scripts" / script).is_file():
            broken.append((hid, script))
    return {"decided_without_a_script": unbacked, "named_script_missing": broken,
            "ok": not unbacked and not broken}


def counts() -> dict:
    out = {s: 0 for s in STATUSES}
    for rec in HYPOTHESES:
        out[rec[6]] += 1
    out["total"] = len(HYPOTHESES)
    return out


def render() -> str:
    c = counts()
    lines = [
        "# Hypotheses from cross-referenced walls",
        "",
        "Generated by `python3 scripts/hypotheses.py`. **Do not edit by hand.**",
        "",
        "A wall alone is a place we got stuck. Paired with another it is a constraint, and constraints generate",
        "hypotheses: *what must also be true for both to hold at once?*",
        "",
        f"**{c['open']} open · {c['supported']} supported · {c['refuted']} refuted · {c['total']} total**",
        "",
        "Every hypothesis cites at least two walls **that exist in the wall register** — the link is checked by",
        "`check_links()`, so a hypothesis cannot float free of the walls that motivated it.",
        "",
        "**The claims-registry rule:** a hypothesis whose status is `supported` or `refuted` **must name a script that",
        "exists in the repository**; `open` may say \"no executable test\". A decided hypothesis with no artefact is a",
        "claim nobody can re-run. `check_artefacts()` enforces it and `scripts/hypotheses.py --check` fails on it.",
        "",
    ]
    belief = {hid: (p, b, post) for hid, p, b, post in belief_view()}
    for hid, title, cited, claim, predicts, test, status, script in HYPOTHESES:
        lines += [f"## {hid} — {title}", ""]
        lines += [f"**status:** {status}" + (f" · **script:** `scripts/{script}`" if script else
                                             " · **script:** none (no executable test)"), ""]
        p, b, post = belief[hid]
        if status == "open":
            lines += [f"**belief:** prior {p:.2f} — no test yet", ""]
        else:
            lines += [f"**belief:** prior {p:.2f} → B {b:.2f} → posterior {post:.2f}", ""]
        lines += ["**pairs these walls:**"] + [f"- {w}" for w in cited] + [""]
        lines += [f"**claim.** {claim}", "", f"**predicts.** {predicts}", "",
                  f"**test.** {test}", ""]
    return "\n".join(lines) + "\n"


__all__ = ["HYPOTHESES", "STATUSES", "DECIDED", "BELIEF_PRIOR", "STANDARD_TEST",
           "belief_view", "check_links", "check_artefacts", "counts", "render"]
